<?php

declare(strict_types=1);

namespace App\Infrastructure\Encounter;

use App\Domain\Encounter\Port\WeatherBoostTable;
use App\Domain\Pokemon\Model\PokemonType;
use App\Domain\Weather\Model\GameWeather;
use App\Infrastructure\Json\JsonPath;
use App\Infrastructure\Json\JsonValue;

/**
 * Reads the weather table generated by `pogo:data:build`.
 */
final class JsonFileWeatherBoostTable implements WeatherBoostTable
{
    /** @var array<string, list<PokemonType>>|null */
    private ?array $boosted = null;

    public function __construct(
        private readonly string $file,
    ) {}

    #[\Override]
    public function boostedTypes(GameWeather $weather): array
    {
        return $this->load()[$weather->value] ?? [];
    }

    /**
     * @return array<string, list<PokemonType>>
     */
    private function load(): array
    {
        if (null !== $this->boosted) {
            return $this->boosted;
        }

        if (!is_file($this->file)) {
            throw new \RuntimeException(\sprintf(
                'Weather file "%s" is missing; run "bin/console pogo:data:build".',
                $this->file,
            ));
        }

        $document = JsonValue::asArray(json_decode(
            (string) file_get_contents($this->file),
            true,
            flags: \JSON_THROW_ON_ERROR,
        ));
        $boosted = [];

        // Narrowing through array_map keeps the keys and leaves no `mixed` in a variable.
        $lists = array_map(JsonValue::asStringList(...), JsonPath::arrayAt($document, 'boostedTypes') ?? []);

        foreach ($lists as $weather => $types) {
            $boosted[(string) $weather] = array_values(array_filter(array_map(PokemonType::tryFrom(...), $types)));
        }

        return $this->boosted = $boosted;
    }
}
